import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for project in data.get('projects', []):
        pname = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            tf = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tf)
                pkgs[key] = pkg['resolvedVersion']
        result[pname] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        pkg_id, tf = key
        if bv != av:
            changes.append((proj, pkg_id, tf, bv, av))
        else:
            unchanged.append((proj, pkg_id, tf, bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} | {c[1]} ({c[2]}): {c[3]} -> {c[4]}')
else:
    print('  None - conversion is version-neutral')

print(f'\n=== UNCHANGED: {len(unchanged)} package-framework pairs ===')
"

